<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function kimpu_get_related_posts( $post_id = 0, $limit = 3 ) { $post_id = $post_id ? absint( $post_id ) : get_the_ID(); if ( ! $post_id ) { return new WP_Query( array( 'post__in' => array( 0 ) ) ); } $args = kimpu_blog_related_query_args( $post_id, $limit ); $query = new WP_Query( $args ); if ( $query->post_count < $limit ) { $existing = wp_list_pluck( $query->posts, 'ID' ); $fallback = new WP_Query( array( 'post_type' => 'post', 'post_status' => 'publish', 'posts_per_page' => $limit - $query->post_count, 'post__not_in' => array_merge( array( $post_id ), $existing ), 'ignore_sticky_posts' => true, 'no_found_rows' => true ) ); $query->posts = array_merge( $query->posts, $fallback->posts ); $query->post_count = count( $query->posts ); } return $query; }
